  "importExport.biblica.paragraphsSkipped": {"forms":{"one":"{count} शास्त्र अनुच्छेद छोड़ा गया।","other":"{count} शास्त्र अनुच्छेद छोड़े गए।"},"countVar":"count"},
  "importExport.bibleSwap.legend": "बाइबल अदला-बदली (वैकल्पिक)",
  "importExport.bibleSwap.intro": "राउंड-ट्रिप आपके अनुवादित नोट मूल Biblica IDML में निर्यात करता है। वैकल्पिक रूप से एक अनुवादित बाइबल फ़ाइल जोड़ें ताकि अंग्रेज़ी आयत पाठ भी मेल खाते शास्त्र से बदले, और नोट तथा बाइबल पाठ एक फ़ाइल में जाएँ। केवल नोट निर्यात करने के लिए मोड केवल नोट पर छोड़ें।",
  "importExport.bibleSwap.modeLegend": "प्रतिस्थापन मोड",
  "importExport.bibleSwap.modeGroupAriaLabel": "बाइबल अदला-बदली प्रतिस्थापन मोड",
